head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/bns_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
scwin.vScrenID = "ULDBNS30300.xml";
scwin.vSelObj;
scwin.processGp;
scwin.vRowCount = 0;
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.vMktCd = '';
scwin.vStrtDd = '';
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/********************************************** 
 * 함수명   : fn_SearchClsDtl
 * 설명       : 상장마감 종목정보 조회한다.
 ***********************************************/
scwin.fn_SearchClsDtl = function() {
    var param = '';
    param += "&{P}V_BND_MKTACT_TP_CD=" + scwin.vMktCd;
    var qryId = '';
    if (scwin.processGp == '1') {
        qryId = scwin.fn_GetQryId();
        param += "&{P}V_STRT_DD=" + $c.stf.getObjectValue(edt_StrtDd);
        // 분할상환 전송관련 추가 JACKAL_190220
        param += "&{P}V_CLS_DD=" + $c.stf.getObjectValue(edt_PrsntDd);
    } else if (scwin.processGp == '2') {
        qryId = scwin.fn_GetQryIdEnd();
        param += "&{P}V_STRT_DD=" + dts_CheckCls.getCellData(1, 'END_CLS_DD');
    }
    var dsNm = 'BNS_CLS_ISU_INFO';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_IsuList, dsNm, qryId, param);
    $c.cm.ShowWin(grd_IsuList);
};


/********************************************** 
 * 함수명   : fn_SearchSendData
 * 설명       : 매매전송 종목정보 조회한다.
 ***********************************************/
scwin.fn_SearchSendData = function() {
    var param = '';
    param += "&{P}V_CLS_DD=" + $c.stf.getObjectValue(edt_BizClsDd);
    param += "&{P}V_STRT_DD=" + $c.stf.getObjectValue(edt_StrtDd);
    var qryId = 'lds.stf.bnscls.select.listClsEndSendInfo';
    var dsNm = 'BNS_SEND_ISU_INFO';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_SendInfo, dsNm, qryId, param);
    $c.cm.ShowWin(grd_SendList);
};


/********************************************** 
 * 함수명   : fn_SearchSendData1
 * 설명       : 매매전송 종목정보 조회한다.
 ***********************************************/
scwin.fn_SearchSendData1 = function() {
    var param = '';
    param += "&{P}V_CLS_DD=" + $c.stf.getObjectValue(edt_BizClsDd);
    param += "&{P}V_STRT_DD=" + dts_CheckCls.getCellData(1, 'END_CLS_DD');
    var qryId = 'lds.stf.bnscls.select.listClsEndSendInfo';
    var dsNm = 'BNS_SEND_ISU_INFO';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_SendInfo1, dsNm, qryId, param);
};


/********************************************** 
 * 함수명   : fn_SearchCls
 * 설명       : 상장마감 조회한다.
 ***********************************************/
scwin.fn_SearchCls = function() {
    var param = '';
    param += "&{P}V_STRT_DD=" + $c.stf.getObjectValue(edt_StrtDd);
    // 분할상환 전송관련 추가 JACKAL_190220
    param += "&{P}V_CLS_DD=" + $c.stf.getObjectValue(edt_PrsntDd);
    var dsNm = 'BNS_CLS_LIST';
    var qryId = 'lds.stf.bnscls.select.listCls';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_MktList, dsNm, qryId, param);
    $c.cm.ShowWin(grd_MktList);
};


/********************************************** 
 * 함수명   : fn_SearchSendIsuInfo
 * 설명       : 상장마감완료 전송정보 조회한다.
 ***********************************************/
scwin.fn_SearchSendIsuInfo = function() {
    var param = '';
    param += "&{P}V_TASK_DD=" + $c.stf.getObjectValue(edt_BizClsDd);
    var dsNm = 'BNS_CLS_SEND_INFO';
    var qryId = 'lds.stf.bnscls.select.listClsSendInfo';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_ClsSendInfo, dsNm, qryId, param);
    $c.cm.ShowWin(grd_ClsSendInfo);
};


/********************************************** 
 * 함수명   : fn_SearchClsEnd
 * 설명       : 상장마감한 데이터 조회한다.
 ***********************************************/
scwin.fn_SearchClsEnd = function() {
    var param = '';
    param += "&{P}V_STRT_DD=" + dts_CheckCls.getCellData(1, 'END_CLS_DD');
    var dsNm = 'BNS_CLS_LIST';
    var qryId = 'lds.stf.bnscls.select.listClsEnd';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_MktList, dsNm, qryId, param);
    $c.cm.ShowWin(grd_MktList1);
};


/********************************************** 
 * 함수명   : fn_SearchClsDd
 * 설명       : 마감일 데이터 조회한다.
 ***********************************************/
scwin.fn_SearchClsDd = function(clsDd) {
    var param = '';
    param += "&{P}V_STRT_DD=" + clsDd;
    var dsNm = 'BNS_CHECK_CLS_DD';
    var qryId = 'lds.stf.bnscls.select.readChkClsDd';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_CheckCls, dsNm, qryId, param);
};


/********************************************** 
 * 함수명   : fn_ClsProcs
 * 설명       : 마감처리 한다.
 ***********************************************/
scwin.fn_ClsProcs = function() {
    var param = '';
    param += "&{P}V_STRT_DD=" + $c.stf.getObjectValue(edt_StrtDd);
    var dsNm = 'BNS_CHECK_CLS_PROC';
    var qryId = 'lds.stf.bnscls.select.readChkClsProc';
    dts_CheckClsProc.SyncLoad = "true";
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_CheckClsProc, dsNm, qryId, param);

    //채권마감이력 확인
    if (dts_CheckClsProc.getCellData(1, 'VALID_SEND_CFM') != 'Y') {
        $c.win.alert('시장조치내역생성 처리를 하십시오.');
        return;
    }
    if (dts_CheckClsProc.getCellData(1, 'VALID_BND_CLS') == 'Y') {
        $c.win.alert('업무마감작업이 이미 종료되었습니다.');
        return;
    }
    if (!window.confirm($c.stf.getMessageParam("MSG-A006", "상장마감"))) return;
    var url = "/bns/ListCls.do?method=processCls";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
    var param = "STRT_DD=" + $c.stf.getObjectValue(edt_StrtDd);
    // 분할상환 전송관련 추가 JACKAL_190220
    param += ",CLS_DD=" + $c.stf.getObjectValue(edt_PrsntDd);
    trs_Save.Action = $c.lc.fn_encodeNSession(url);
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_Temp)";
    trs_Save.Parameters = param;
    trs_Save.Post();
};


/********************************************** 
 * 함수명   : fn_SendCfm
 * 설명       : 전송내역 생성 한다.
 ***********************************************/
scwin.fn_SendCfm = function() {
    //발행기관 데이터 (종목명, 주소 등) 완성형한글 체크
    var urlck = "/bns/ListCls.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=processCompleteKoreanCheck";
    urlck += "&outputMessageId=BNS_CHECK_CLS_COMPLETE_KOREAN";
    urlck += "&STRT_DD=" + $c.stf.getObjectValue(edt_StrtDd);
    dts_completeKorean.SyncLoad = "true";
    dts_completeKorean.DataID = encodeURI(urlck);
    dts_completeKorean.Reset();
    var div = dts_completeKorean.getCellData(1, 'DIV');
    var isurCd = dts_completeKorean.getCellData(1, 'ISUR_CD');
    var comNm = dts_completeKorean.getCellData(1, 'COM_NM');
    var comAbbrv = dts_completeKorean.getCellData(1, 'COM_ABBRV');
    var msg = '';
    if (div == '1') {
        msg += ' 금일 발행기관 데이터에 문제가 있습니다.';
        msg += '\n\n 문제발생 발행기관코드 : ' + isurCd;
        msg += '\n 문제발생 발행기관명 : ' + comNm;
    } else if (div == '2') {
        msg += '금일 채권마스터 데이터에 문제가 있습니다.';
        msg += '\n\n 문제발생 표준코드 : ' + isurCd;
        msg += '\n 문제발생 한글종목명 : ' + comNm;
    }
    msg += '\n\n 시스템담당자에게 연락바랍니다.';
    msg += '\n\n 계속 진행하시겠습니까?';
    if (dts_completeKorean.getTotalRow() > 0) {
        if (!window.confirm(msg)) {
            scwin.processGp = '1';
            return;
        }
    }
    var param = '';
    param += "&{P}V_STRT_DD=" + $c.stf.getObjectValue(edt_StrtDd);
    var dsNm = 'BNS_CHECK_CLS_PROC';
    var qryId = 'lds.stf.bnscls.select.readChkClsProc';
    dts_CheckClsProc.SyncLoad = "true";
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_CheckClsProc, dsNm, qryId, param);
    if (dts_CheckClsProc.getCellData(1, 'VALID_BND_CLS') == 'Y') {
        $c.win.alert('업무마감작업이 이미 종료되었습니다.');
        return;
    }

    //발행기관, 채권마스터 종목명에 엔터값 있는지 확인
    var stdCd = dts_CheckClsProc.getCellData(1, 'STD_CD');
    var stdCdAppl = dts_CheckClsProc.getCellData(1, 'STD_CD_APPL'); // jackal_140819 라인구분체크 추가
    var isurCd = dts_CheckClsProc.getCellData(1, 'ISUR_CD');
    var msg = '금일 발행기관, 채권마스터 데이터에 문제가 있습니다.';
    msg += '\n 문제발생 발행기관코드 : ' + isurCd;
    msg += '\n 문제발생 채권마스터코드 : ' + stdCd;
    msg += '\n 문제발생 신청마스터코드 : ' + stdCdAppl;
    msg += '\n 시스템담당자에게 연락바랍니다.';
    if (isurCd != '' || stdCd != '' || stdCdAppl != '') {
        $c.win.alert(msg);
        return;
    }

    //금일 수신된 신용등급정보를 처리했는지 확인.
    if (dts_CheckClsProc.getCellData(1, 'HAS_CREDIT_RCV') == 'Y') {
        if (dts_CheckClsProc.getCellData(1, 'VALID_CREDIT_RCV') == 'Y') {
            $c.win.alert('금일 수신된 신용등급정보를 처리하지 않았습니다.\n 신용평가 수신내역을 확인바랍니다.');
            return;
        }
    }
    //스트립 통합처리 완료 확인.
    if (dts_CheckClsProc.getCellData(1, 'VALID_STRIP') == 'Y') {
        $c.win.alert('마감처리 전 스트립 통합처리를 하시기 바랍니다.');
        return;
    }
    if (dts_CheckClsProc.getCellData(1, 'VALID_STRIP') == 'F') {
        $c.win.alert("스트립 시장조치(스트립신규, 추가 및 재결합)와\n\n'스트립 통합처리' 화면내용이 불일치함.\n\n'스트립 통합처리'를 취소 후 다시 진행바람.");
        return;
    }

    //종목중복체크
    qryId = 'lds.stf.bnscls.select.listCheckListIsuDupl';
    dts_CheckDup.SyncLoad = "true";
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_CheckDup, dsNm, qryId, param);
    if (dts_CheckDup.getTotalRow() > 0) {
        var dupMsg = '';
        for (var idx = 1; idx <= dts_CheckDup.getTotalRow(); idx++) {
            dupMsg += dts_CheckDup.getCellData(idx, 'DUP_ISU') + '\n';
        }
        dupMsg += '로 중복조치되었습니다.\n확인 후 다시 처리하여 주십시오.';
        $c.win.alert(dupMsg);
        return;
    }
    if (!window.confirm($c.stf.getMessageParam("MSG-A006", "시장조치내역생성"))) return;
    var url = "/bns/ListCls.do?method=processSendCfm";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
    var param = "STRT_DD=" + $c.stf.getObjectValue(edt_StrtDd);
    // 분할상환 전송관련 추가 JACKAL_190220
    param += ",CLS_DD=" + $c.stf.getObjectValue(edt_PrsntDd);
    trs_Save.Action = $c.lc.fn_encodeNSession(url);
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_Temp)";
    trs_Save.Parameters = param;
    trs_Save.Post();
};


/********************************************** 
 * 함수명   : fn_ReClsProcs
 * 설명       : 재마감처리 한다.
 ***********************************************/
scwin.fn_ReClsProcs = function() {
    scwin.processGp = '9';
    var param = '';
    param += "&{P}V_STRT_DD=" + $c.stf.getObjectValue(edt_StrtDd);
    var dsNm = 'BNS_CHECK_CLS_PROC';
    var qryId = 'lds.stf.bnscls.select.readChkClsProc';
    dts_CheckClsProc.SyncLoad = "true";
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_CheckClsProc, dsNm, qryId, param);

    //채권마감이력 확인
    var msg = '';
    //시장조치반영완료
    if (dts_CheckClsProc.getCellData(1, 'VALID_BND_CLS1') == 'Y') {
        $c.win.alert('이미 일일 시장조치반영이 완료 되었습니다.');
        return;
    }
    if (dts_CheckClsProc.getCellData(1, 'VALID_BND_CLS') == 'Y') {
        msg += '채권송신(매매)데이타를 다시 생성하여 송신 할 경우에 해당합니다.';
        msg += '\n다음 데이타가 클리어(Delete)됩니다.';
        msg += '\n- 채권마감이력';
        msg += '\n- 시장조치 전송내역';
        msg += '\n- 신용평가 전송내역';
        $c.win.alert(msg);
    } else {
        msg += '업무마감이 되지 않아 업무마감처리를';
        msg += '\n다시 하실수 없습니다.';
        $c.win.alert(msg);
        return;
    }
    if (!window.confirm($c.stf.getMessageParam("MSG-A006", "재마감처리"))) return;
    dts_SendInfo.removeAll();
    dts_List.removeAll();
    var url = "/bns/ListCls.do?method=reProcessCls";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
    var param = "STRT_DD=" + $c.stf.getObjectValue(edt_StrtDd);
    trs_Save.Action = $c.lc.fn_encodeNSession(url);
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_Temp)";
    trs_Save.Parameters = param;
    trs_Save.Post();
};


/********************************************** 
 * 함수명   : fn_GetParMktFile
 * 설명       : 시장지파일 팝업에 넘길 데이터를 정의한다.
 ***********************************************/
scwin.fn_GetParMktFile = function(arrPar) {
    arrPar[0] = {
        TRD_DD: $c.stf.getObjectValue(edt_BizClsDd)
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};


/********************************************** 
 * 함수명   : fn_GetParIsuDtlAndMktactDtl
 * 설명       : 시장조치상세내역 팝업에 넘길 데이터를 정의한다.
 ***********************************************/
scwin.fn_GetParIsuDtlAndMktactDtl = function(arrPar) {
    arrPar[0] = {
        STD_CD: dts_IsuList.getCellData(dts_IsuList.getRowPosition(), 'STD_CD'),
        STRT_DD: dts_IsuList.getCellData(dts_IsuList.getRowPosition(), 'STRT_DD')
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};


/********************************************** 
 * 함수명   : fn_IntiIsuCol
 * 설명       : 종목정보를 초기화한다.
 ***********************************************/
scwin.fn_IntiIsuCol = function() {
    grd_IsuList.Redraw = false;
    scwin.fn_showFalse();

    //상호변경
    if (scwin.vMktCd == '201') scwin.fn_show201();
    //합병/회사분할


    else if (scwin.vMktCd == '202') scwin.fn_show202();
    //종목분할


    else if (scwin.vMktCd == '203') scwin.fn_show202();
    //변경상장종목분할


    else if (scwin.vMktCd == '105') scwin.fn_show105();
    //BW 신주인수권행사


    else if (scwin.vMktCd == '205') scwin.fn_show205();
    //BW 분리종목


    else if (scwin.vMktCd == '104') scwin.fn_show104();
    //일괄상장채권 상장금액조정(월별,일별) 301,320


    else if (scwin.vMktCd == '301' || scwin.vMktCd == '320') scwin.fn_show301320();
    //주식관련사채 권리행사 302


    else if (scwin.vMktCd == '302') scwin.fn_show302();
    //중도상환 303,304


    else if (scwin.vMktCd == '303' || scwin.vMktCd == '304') scwin.fn_show303304();
    //국고채추가발행 305


    else if (scwin.vMktCd == '305') scwin.fn_show305();
    //권리행사가액 변경 306


    else if (scwin.vMktCd == '306') scwin.fn_show306();
    //발행가액 변경 307


    else if (scwin.vMktCd == '307') scwin.fn_show307();
    //표면이자율,FRN 변동금리 변경 308, 309


    else if (scwin.vMktCd == '308' || scwin.vMktCd == '309') scwin.fn_show308309();
    //옵션상환일 변경 311


    else if (scwin.vMktCd == '311') scwin.fn_show311();
    //수동상장폐지 314


    else if (scwin.vMktCd == '314') scwin.fn_show314();
    //기타변경 316


    else if (scwin.vMktCd == '316') scwin.fn_show316();
    //BW(일반사채)권리행사 315


    else if (scwin.vMktCd == '315') scwin.fn_show315();
    //분할상환정보 JACKAL_190220


