    //WIT종목정보확정


    else if (scwin.vMktCd == '330') scwin.fn_show330();
    //default


    else {
        //국채,지방채,특수채,회사채,외국채권 신규상장
        scwin.fn_showDefault();
    }
    grd_IsuList.Redraw = true;
};

