 * 함수명   : fn_SearchMktact
 * 설명       : 시장조치내역 조회한다.
 ***********************************************/
scwin.vStdCd;
scwin.fn_SearchMktact = function() {
    var param = '';
    param += "&{P}V_STD_CD=" + scwin.vStdCd;
    param += "&{P}V_STRT_DD=" + $c.stf.getObjectValue(edt_StrtDd);
    param += "&{P}V_APPL_YN=N";
    //param += "&{P}V_STD_CD=KR6015861S58";

    var dsNm = 'BNS_MKTACT_DTL';
    var qryId = 'lds.stf.bnscommon.select.listMktactDtlMulty';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_List, dsNm, qryId, param);
};


/********************************************** 
 * 함수명   : fn_SearchMktact1
 * 설명       : 시장조치내역 조회한다.
 ***********************************************/
scwin.vClsApplyYn;
scwin.fn_SearchMktact1 = function() {
    var param = '';
    param += "&{P}V_STD_CD=" + scwin.vStdCd;
    param += "&{P}V_STRT_DD=" + dts_CheckCls.getCellData(1, 'END_CLS_DD');
    //param += "&{P}V_STD_CD=KR6015861S58";

    var dsNm = 'BNS_MKTACT_DTL';
    var qryId = 'lds.stf.bnscommon.select.listMktactDtlMulty';
    if (scwin.vClsApplyYn == 'Y') {
        param += "&{P}V_APPL_YN=Y";
    } else {
        param += "&{P}V_APPL_YN=N";
    }
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_List1, dsNm, qryId, param);
};
scwin.gform_onload = function() {
    //숨기기
    if (js_usr_tp_cd == '1') {
        //운영자이면
        $c.stf.showObj(btn_ReClsProcs, true);
    } else {
        $c.stf.showObj(btn_ReClsProcs, false);
    }

    //탭선택
    tab_List.setSelectedTabIndex(1);
    tab_ListCls.setSelectedTabIndex(1);
    tab_ListCls1.setSelectedTabIndex(1);

    //패널라운드처리
    $c.bns.BnsPanelToGroupBox(pnl_Item);
    $c.bns.BnsPanelToGroupBox(pnl_Item2);
    $c.bns.BnsPanelToGroupBox(pnl_Cls);
    $c.bns.BnsPanelToGroupBox(pnl_ClsDtl);
    $c.bns.BnsPanelToGroupBox(pnl_SendDtl);
    $c.bns.BnsPanelToGroupBox(pnl_ClsDtl1);
    $c.bns.BnsPanelToGroupBox(pnl_SendDtl1);

    //종목정보 컬럼 초기화
    scwin.fn_IntiIsuCol();

    //마감조회
    scwin.processGp = '1';
    scwin.fn_SearchClsDd('');

    //임시데이터셋설정

    //dts_Temp.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
    dts_Temp.insertRow();
};
scwin.btn_Search_onclick = function() {
    if ($c.stf.getObjectValue(edt_BizClsDd) == '') {
        $c.win.alert('업무마감일을 입력 하십시오.');
        return;
    }
    scwin.processGp = '2';
    scwin.fn_SearchClsDd($c.stf.getObjectValue(edt_BizClsDd));
};
scwin.dts_MktList_OnLoadCompleted = function(rowcount) {
    scwin.vRowCount = rowcount;
    $c.cm.CloseWin(rowcount, grd_MktList);
    if (rowcount == 0) {
        dts_MktList.removeAll();
        dts_IsuList.removeAll();
        $c.cm.setColumnProp(grd_MktList, 'BND_MKTACT_TP_NM', 'Name', "총 0 건");
        if (scwin.processGp == '2') {
            $c.cm.setColumnProp(grd_MktList1, 'BND_MKTACT_TP_NM', 'Name', "총 0 건");
        }
    } else {
        //최종호가,CD최종호가 조회
        //fn_SearchLastOrdYd();		
        //헤더설정
        if (scwin.processGp == '1') {
            $c.cm.setColumnProp(grd_MktList, 'BND_MKTACT_TP_NM', 'Name', "마감전 : 총 " + dts_MktList.getCellData(1, "TOT_MKTACT_CNT") + "건");
        } else {
            $c.cm.setColumnProp(grd_MktList1, 'BND_MKTACT_TP_NM', 'Name', "총 " + dts_MktList.getCellData(1, "TOT_MKTACT_CNT") + "건");
        }
    }
    //종목전송정보조회
    if (scwin.processGp == '2') {
        scwin.fn_SearchSendIsuInfo();
    }
};
scwin.dts_ClsSendInfo_OnLoadCompleted = function(rowcount) {
    $c.cm.CloseWin(rowcount, grd_ClsSendInfo);
};
scwin.dts_MktList_OnLoadError = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0002"));
    $c.stf.alert_error(dts_MktList);
};
scwin.dts_MktList_OnRowPosChanged = function(row) {
    dts_IsuList.removeAll();
    if (row == 0) return;
    scwin.vMktCd = dts_MktList.getCellData(row, 'BND_MKTACT_TP_CD');
    var cnt = dts_MktList.getCellData(row, "MKTACT_CNT");

    //종목헤더설정
    if (scwin.processGp == '1') {
        scwin.fn_IntiIsuCol();
    }

    //종목조회
    if (cnt > 0) {
        scwin.fn_SearchClsDtl();
    }
};
scwin.trs_Save_OnFail = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0002"));
    $c.stf.alert_error(trs_Save);
};
scwin.trs_Save_OnSuccess = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0001"));
    scwin.processGp = '1';
    scwin.fn_SearchClsDd('');
};
scwin.dts_CheckCls_OnLoadCompleted = function(rowcount) {
    if ($c.stf.getObjectValue(edt_BizClsDd) == '') {
        $c.stf.setObjectValue(edt_BizClsDd, dts_CheckCls.getCellData(1, 'PRSNT_DD'));
    }
    if (scwin.processGp == '1') {
        $c.stf.setObjectValue(edt_PrsntDd, dts_CheckCls.getCellData(1, 'PRSNT_DD'));
        $c.stf.setObjectValue(edt_StrtDd, dts_CheckCls.getCellData(1, 'CLS_DD'));
        scwin.vStrtDd = $c.stf.getObjectValue(edt_StrtDd);
        scwin.fn_SearchSendData();
        var param = '';
        param += "&{P}V_STRT_DD=" + $c.stf.getObjectValue(edt_StrtDd);
        var dsNm = 'BNS_CHECK_CLS_PROC';
        var qryId = 'lds.stf.bnscls.select.readChkClsProc';
        dts_CheckClsProc.SyncLoad = "true";
        $c.bns.fn_SearchBns(scwin.vScrenID, dts_CheckClsProc, dsNm, qryId, param);
        if (dts_CheckClsProc.getCellData(1, 'VALID_BND_CLS') == 'Y') {
            $c.stf.setObjectValue(txb_ClsDtl, '* 마감처리 완료');
        } else if (dts_CheckClsProc.getCellData(1, 'VALID_SEND_CFM') == 'Y') {
            $c.stf.setObjectValue(txb_ClsDtl, '* "상장마감"이 완료되지 않았습니다. 상장마감 시 "시장조치내역생성" 후 "상장마감" 하시기 바랍니다.');
            tab_ListCls.setSelectedTabIndex(2);
        } else {
            $c.stf.setObjectValue(txb_ClsDtl, '* "상장마감"이 완료되지 않았습니다. 상장마감 시 "시장조치내역생성" 후 "상장마감" 하시기 바랍니다.');
        }
        scwin.fn_SearchCls();
    } else if (scwin.processGp == '2') {
        if (dts_CheckCls.getCellData(1, "VALID_BIZ_CLS_DD") == "Y") {
            $c.win.alert("업무마감일이 아닙니다.");
            dts_MktList.removeAll();
            dts_SendInfo1.removeAll();
            dts_List1.removeAll();
            dts_ClsSendInfo.removeAll();
            dts_IsuList.removeAll();
            $c.cm.setColumnProp(grd_MktList1, 'BND_MKTACT_TP_NM', 'Name', "총 0 건");
            return;
        }
        scwin.fn_SearchClsEnd();
        scwin.fn_SearchSendData1();
    }
};
